const HOUR_MS = 60 * 60 * 1000;

function throttleKey(notifier, user, message) {
  const category = message.category || 'general';
  return `${notifier.channel}:${user.id}:${category}`;
}

function checkHourlyLimit(notifier, user, message, options) {
  if (options.force || message.priority === 'urgent') {
    return { throttled: false };
  }

  const key = throttleKey(notifier, user, message);
  const now = notifier.now().getTime();
  const records = (notifier.throttleStore.get(key) || []).filter(ts => now - ts < HOUR_MS);

  if (records.length >= notifier.maxPerHour) {
    return {
      throttled: true,
      reason: `${notifier.channel} hourly limit reached`,
      retryAt: new Date(records[0] + HOUR_MS).toISOString()
    };
  }

  return { throttled: false };
}

// Exemptions skip every check. The marketing opt-in check runs after the hourly
// limit, so `force` and urgent priority do not bypass it.
function shouldThrottle(notifier, strategy, user, message, options) {
  if (strategy.isThrottleExempt && strategy.isThrottleExempt(message, options)) {
    return { throttled: false };
  }

  const limit = checkHourlyLimit(notifier, user, message, options);
  if (limit.throttled) {
    return limit;
  }

  const optIn = strategy.marketingOptIn;
  if (optIn && message.category === 'marketing' && !user[optIn.flag]) {
    return {
      throttled: true,
      reason: `user has not opted into marketing ${optIn.label}`,
      retryAt: null
    };
  }

  return { throttled: false };
}

function recordDelivery(notifier, user, message) {
  const key = throttleKey(notifier, user, message);
  const records = notifier.throttleStore.get(key) || [];
  records.push(notifier.now().getTime());
  notifier.throttleStore.set(key, records);
}

module.exports = {
  shouldThrottle,
  throttleKey,
  recordDelivery
};
